struct LocalFactory;
impl LocalFactory { fn new() -> Self { Self } fn make<T>() -> Self { Self } }
fn helper() {}
fn caller() {
    wrapper!(::foreign::helper(), foreign::nested::helper(), Vec::<u8>::new(),
        LocalFactory::make::<u8>(), foreign::make::<u8>());
}
